class Board:
    def __init__(self, id, family, title, principle, *aliases):
        self.id = id
        self.family = family
        self.board = "robot"
        self.title = title
        self.principle = principle
        self.aliases = aliases


ROWS = [Board(*row) for row in _RAW]
_BY_ID = {row.id: row for row in ROWS}
_ALIASES = sorted(((alias, row) for row in ROWS for alias in row.aliases), key=lambda item: len(item[0]), reverse=True)
_ASK = re.compile(r"\b(what|explain|define|meaning|difference|which)\b")
_LIST = re.compile(r"\b(list|taxonomy|categories|category)\b")
_REF = re.compile(r"\b(?:tp|sw|[rcdlqjuy])\d+\b")
_VERB = re.compile(r"\b(place|connect|tie|wire|move|delete|route|remove)\b")


def families() -> str:
    counts = {key: 0 for key in _FAMILY}
    for row in ROWS:
        counts[row.family] = counts.get(row.family, 0) + 1
    parts = [f"{_FAMILY[key]} ({counts[key]})" for key in _FAMILY if counts.get(key)]
    return f"Robotics families: {', '.join(parts)}. {len(ROWS)} boards. {_LIMIT}"


def find(text: str) -> Board | None:
    low = re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()
    if _REF.search(low) and _VERB.search(low):
        return None
    padded = f" {low} "
    for alias, row in _ALIASES:
        if f" {alias} " in padded:
            return row
    return None


def describe(kind: str) -> tuple[str, str] | None:
    row = _BY_ID.get(kind)
    if row is None:
        return None
    return row.title, f"{row.title}. {row.principle} {_PROFILE} {_LIMIT} Board class stored."


def _span(text: str, row: Board) -> int:
    low = re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()
    padded = f" {low} "
    return max((len(alias) for alias in row.aliases if f" {alias} " in padded), default=0)


def lookup(text: str) -> dict | None:
    low = re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()
    if _LIST.search(low) and any(word in low.split() for word in ("robot", "robotics", "robots")):
        return {"mode": "ask", "id": "", "text": families(), "span": 0}
    row = find(text)
    if row is not None:
        text_out = f"{row.title}. {row.principle} {_PROFILE} {_LIMIT}"
        span = _span(text, row)
        if _ASK.search(low):
            return {"mode": "ask", "id": row.id, "text": text_out, "span": span}
        return {"mode": "set", "id": row.id, "text": text_out + " Board class stored.", "span": span}
    if "humanoid" in low.split():
        body = "Humanoid priority boards: " + "; ".join(_HUMANOID) + f". {_LIMIT}"
        return {"mode": "ask", "id": "humanoid", "text": body, "span": 0}
    for key, title, example in _PRODUCTS:
        if key in low:
            return {"mode": "ask", "id": key.replace(" ", "_"), "text": f"{title}: {example}. {_LIMIT}", "span": len(key)}
    return None


def tokens() -> list[str]:
    words = set()
    for row in ROWS:
        words.add(row.id)
        words.add(row.family)
        for alias in row.aliases:
            words.update(alias.split())
    return sorted(words)

